            Triple("Failed", "Failed#0", { vexlife.voiceinput.VexLifeVoiceInputFamily.Failed(reason = vexlife.voiceinput.VexLifeVoiceInputFamily.FailureReason.MicrophonePermissionRequired) }),
            Triple("Failed", "Failed#1", { vexlife.voiceinput.VexLifeVoiceInputFamily.Failed(reason = vexlife.voiceinput.VexLifeVoiceInputFamily.FailureReason.MicrophoneUnavailable) }),
            Triple("Failed", "Failed#2", { vexlife.voiceinput.VexLifeVoiceInputFamily.Failed(reason = vexlife.voiceinput.VexLifeVoiceInputFamily.FailureReason.RecognitionStopped) }),
            Triple("Failed", "Failed#3", { vexlife.voiceinput.VexLifeVoiceInputFamily.Failed(reason = vexlife.voiceinput.VexLifeVoiceInputFamily.FailureReason.Unknown) }),
        )
        val controls: List<Triple<String, String, () -> vexlife.voiceinput.VexLifeVoiceInputFamily.Control>> = listOf(
            Triple("Start", "Start", { vexlife.voiceinput.VexLifeVoiceInputFamily.Start }),
            Triple("Stop", "Stop", { vexlife.voiceinput.VexLifeVoiceInputFamily.Stop }),
        )
        for ((stateVariant, stateFixture, state) in states) {
            for ((controlVariant, controlFixture, control) in controls) {
                cell("VexLifeVoiceInputFamily", stateVariant, stateFixture, controlVariant, controlFixture) {
                    family.resolve(state(), control())?.let { act -> simple(act.admittedState) to simple(act.effect) }
                }
            }
        }
    }

